#define MAXN 100005

typedef struct Edge {
    int to;
    struct Edge *next;
} Edge;

Edge *adj[MAXN];
int dist[MAXN];

void add_edge(int u, int v) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->next = adj[u];
    adj[u] = e;
}

void dfs(int u, int parent) {
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v != parent) {
            dist[v] = dist[u] + 1;
            dfs(v, u);
        }
    }
}

