        add_edge(p, q);
        add_edge(q, p);
    }

    // First DFS from node 1 to find farthest node A
    memset(dist, 0, sizeof(dist));
    dfs(1, 0);
    int far = 1;
    for (int i = 1; i <= n; i++) {
        if (dist[i] > dist[far]) far = i;
    }

    // Second DFS from node far to find farthest distance (diameter)
    memset(dist, 0, sizeof(dist));
    dfs(far, 0);
    int diameter = 0;
    for (int i = 1; i <= n; i++) {
        if (dist[i] > diameter) diameter = dist[i];
