void addedge(int u, int v) {
    to[++cnt] = v; nxt[cnt] = head[u]; head[u] = cnt;
    to[++cnt] = u; nxt[cnt] = head[v]; head[v] = cnt;
}

int bfs(int s) {
    static int q[MAXN];
    memset(dist, -1, sizeof(dist));
    int front=0, back=0;
    q[back++] = s; dist[s] = 0;
    int far = s;
    while(front < back) {
        int u = q[front++];
        for(int e = head[u]; e; e = nxt[e]) {
            int v = to[e];
            if(dist[v] == -1) {
                dist[v] = dist[u]+1;
                if(dist[v] > dist[far]) far = v;
                q[back++] = v;
            }
        }
    }
    return far;
}

