#include <stdio.h>
#include <stdlib.h>

typedef struct Edge {
    int to, next;
} Edge;

static int max(int a, int b) { return a > b ? a : b; }

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    if (N == 1) {
        printf("1\n");
        return 0;
    }

    int *head = (int *)malloc((N + 1) * sizeof(int));
    int *deg  = (int *)calloc(N + 1, sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc((2 * (N - 1)) * sizeof(Edge));
    int ecnt = 0;

    for (int i = 0; i < N - 1; i++) {
        int p, q;
        scanf("%d %d", &p, &q);

        edges[ecnt].to = q;
        edges[ecnt].next = head[p];
        head[p] = ecnt++;
        deg[p]++;

        edges[ecnt].to = p;
        edges[ecnt].next = head[q];
        head[q] = ecnt++;
        deg[q]++;
    }

    /*
      Let chosen vertices be v1, v2, ..., vM.
      The condition means that for each consecutive pair, the path between them
      contains no other chosen vertex. Therefore every chosen vertex can be used
      only as an endpoint of at most two such paths, and in the union of these paths
      the chosen vertices form a simple path in the tree.

      Hence the maximum M equals the maximum number of leaves in any connected subgraph
      that is a path-like Steiner tree, which in a tree is exactly the diameter in terms
      of number of leaves? More directly:
      Any valid sequence corresponds to a simple path in the original tree after suppressing
      unchosen degree-2 vertices, and the chosen vertices are exactly the vertices of that
      reduced path. To maximize their count, we can take all leaves of the original tree
      encountered by moving through branching vertices. This is equivalent to the diameter
      of the "leaf-pruned" tree? Simpler DP below computes the maximum number directly.

      Root the tree arbitrarily.
      dp[u] = maximum number of chosen vertices in a valid sequence entirely inside u's subtree,
              where the sequence starts at u and goes downward, and u is chosen.
      Transition: from u we may continue into at most one child, because in a sequence path
      through u, one side goes to parent and one side to at most one child.
      If u is a leaf in rooted tree, dp[u] = 1.
      Otherwise, dp[u] = max(1, max over children v of dp[v] + (deg[u] != 2 ? 1 : 0)?)

      An easier and correct characterization:
      Compress every maximal chain of degree-2 vertices. In the compressed tree, every
      internal vertex has degree >= 3, leaves have degree 1. Along a compressed edge, we can
      choose only its endpoints unless it is an endpoint of the whole sequence. The optimum
      number of chosen vertices equals the number of vertices on a longest path in the
      compressed tree, counting original endpoints of compressed edges only once.
      This can be computed by assigning weight:
        w[u] = 1 if degree[u] != 2, else 0
      Then answer is maximum weighted path sum, but if N==1 answer=1.
      Because degree-2 vertices cannot be chosen in addition to both neighbors:
      selecting them would block adjacency, so only branching vertices/leaves contribute.
    */

    int *parent = (int *)malloc((N + 1) * sizeof(int));
    int *order = (int *)malloc(N * sizeof(int));
    int front = 0, back = 0;

    parent[1] = 0;
    order[back++] = 1;
    while (front < back) {
        int u = order[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v == parent[u]) continue;
            parent[v] = u;
            order[back++] = v;
        }
    }

    int *down = (int *)malloc((N + 1) * sizeof(int));
    int ans = 1;

    for (int i = N - 1; i >= 0; i--) {
        int u = order[i];
        int wu = (deg[u] == 2 ? 0 : 1);

        int best1 = 0, best2 = 0; // best downward contributions from children
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (v == parent[u]) continue;
            int val = down[v];
            if (val > best1) {
                best2 = best1;
                best1 = val;
            } else if (val > best2) {
                best2 = val;
            }
        }

        down[u] = wu + best1;
        if (down[u] < 1) down[u] = 1; // for pure degree-2 chain endpoints handled by leaves

        int through = wu + best1 + best2;
        if (through < 1) through = 1;
        ans = max(ans, through);
    }

    printf("%d\n", ans);

    free(head);
    free(deg);
    free(edges);
    free(parent);
    free(order);
    free(down);
    return 0;
}

