#include <bits/stdc++.h>
using namespace std;

/*
We need the maximum size of an ordered sequence of distinct vertices
v1, v2, ..., vM such that for every consecutive pair, the path between them
contains no other chosen vertex.

Interpretation:
If we look at the chosen set S = {v1, ..., vM}, then the condition means that
for every consecutive pair in the ordering, they are adjacent in the minimal
subtree induced by S (no other chosen vertex lies on their path).

Thus we need to know whether all chosen vertices can be ordered so that every
consecutive pair are adjacent in the induced Steiner tree on S.

A tree admits a Hamiltonian path using all its vertices iff it is itself a path.
Therefore, the induced subtree on chosen vertices must be a path.
So the problem becomes:

Choose the maximum number of vertices such that the minimal subtree connecting
them is a simple path.

In a tree, that is exactly the number of vertices lying on some simple path.
Hence the answer is the maximum number of vertices on a path in the tree,
i.e. diameter length in vertices.

So compute tree diameter and output number of vertices on it.
*/

pair<int,int> bfs_far(int start, const vector<vector<int>>& g) {
    int n = (int)g.size() - 1;
    vector<int> dist(n + 1, -1);
    queue<int> q;
    q.push(start);
    dist[start] = 0;
    int far = start;
    while (!q.empty()) {
        int v = q.front();
        q.pop();
        if (dist[v] > dist[far]) far = v;
        for (int to : g[v]) {
            if (dist[to] == -1) {
                dist[to] = dist[v] + 1;
                q.push(to);
            }
        }
    }
    return {far, dist[far]};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int p, q;
        cin >> p >> q;
        g[p].push_back(q);
        g[q].push_back(p);
    }

    auto a = bfs_far(1, g);
    auto b = bfs_far(a.first, g);

    // diameter in edges = b.second, so vertices = b.second + 1
    cout << b.second + 1 << '\n';
    return 0;
}

