public class Main {
    static List<Integer>[] adj;
    static int n;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i < n - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int p = Integer.parseInt(st.nextToken());
            int q = Integer.parseInt(st.nextToken());
            adj[p].add(q);
            adj[q].add(p);
        }

        // BFS from vertex 1 to find farthest vertex u
        int u = bfs(1);
        // BFS from u to find farthest vertex v and distance
        int v = bfs(u);
        // diameter in edges = dist, in vertices = dist + 1
        System.out.println(dist[v] + 1);
    }

    static int[] dist;

    static int bfs(int start) {
        dist = new int[n + 1];
        Arrays.fill(dist, -1);
        Queue<Integer> queue = new LinkedList<>();
        queue.add(start);
        dist[start] = 0;
        int farthest = start;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            if (dist[cur] > dist[farthest]) farthest = cur;
            for (int nb : adj[cur]) {
                if (dist[nb] == -1) {
                    dist[nb] = dist[cur] + 1;
                    queue.add(nb);
                }
            }
        }
        return farthest;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static ArrayList<Integer>[] g;
    static int[] parent;
    static int[] order;
    static int[] dp0, dp1;
    // dp0[u]: maximum size in subtree of u, when u is NOT selected
    // dp1[u]: maximum size in subtree of u, when u IS selected

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();
        for (int i = 0; i < N - 1; i++) {
            int p = fs.nextInt() - 1;
            int q = fs.nextInt() - 1;
            g[p].add(q);
            g[q].add(p);
        }

        parent = new int[N];
        Arrays.fill(parent, -1);
        order = new int[N];
        int sz = 0;

        int[] stack = new int[N];
        int top = 0;
        stack[top++] = 0;
        parent[0] = -2;

        while (top > 0) {
            int u = stack[--top];
            order[sz++] = u;
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                stack[top++] = v;
            }
        }

        dp0 = new int[N];
        dp1 = new int[N];

        for (int idx = N - 1; idx >= 0; idx--) {
            int u = order[idx];

            int sumBest = 0;
            int childCountSelected = 0;
            int lossMin1 = Integer.MAX_VALUE;
            int lossMin2 = Integer.MAX_VALUE;

            for (int v : g[u]) {
                if (v == parent[u]) continue;

                int best = Math.max(dp0[v], dp1[v]);
                sumBest += best;

                if (dp1[v] > dp0[v]) {
                    childCountSelected++;
                    int loss = dp1[v] - dp0[v];
                    if (loss < lossMin1) {
                        lossMin2 = lossMin1;
                        lossMin1 = loss;
                    } else if (loss < lossMin2) {
                        lossMin2 = loss;
                    }
                }
            }

            // u not selected:
            // Among children connected through u, at most 2 can have selected vertices
            int val0 = sumBest;
            if (childCountSelected > 2) {
                // Need to turn some selected-child choices into not-selected
                // Keep the two largest gains, equivalently subtract the smallest losses
                // for extra selected children beyond 2
                int[] losses = new int[childCountSelected];
                int ptr = 0;
                for (int v : g[u]) {
                    if (v == parent[u]) continue;
                    if (dp1[v] > dp0[v]) losses[ptr++] = dp1[v] - dp0[v];
                }
                Arrays.sort(losses);
                for (int i = 0; i < childCountSelected - 2; i++) val0 -= losses[i];
            }
            dp0[u] = val0;

            // u selected:
            // Then at most 2 incident used edges total; one may go to parent, so among children at most 1
            int val1 = 1 + sumBest;
            if (childCountSelected > 1) {
                int[] losses = new int[childCountSelected];
                int ptr = 0;
                for (int v : g[u]) {
                    if (v == parent[u]) continue;
                    if (dp1[v] > dp0[v]) losses[ptr++] = dp1[v] - dp0[v];
                }
                Arrays.sort(losses);
                for (int i = 0; i < childCountSelected - 1; i++) val1 -= losses[i];
            }
            dp1[u] = val1;
        }

        System.out.println(Math.max(dp0[0], dp1[0]));
    }
}
